effect.shader:
const float PI = 3.14159265;

// O float que a textura de 8 bits devolve para o nível k (k/255 arredondado como o hardware), montado pelos bits: gravado
// num alvo de 8 bits volta a ser k em qualquer GPU (o `oitoBits` do Equilíbrio de cor).
float oitoBits(float k) {
    uint n = uint(k);
    if (n == 0u) return 0.0;
    if (n == 255u) return 1.0;
    int j = 0;                                                    // o bit mais alto de n
    for (int i = 1; i < 8; i++) if (n >= (1u << uint(i))) j = i;
    int e = 31 - j;
    uint q = ((n << uint(e)) + 127u) / 255u;                      // entre 2^23 e 2^24
    return uintBitsToFloat((uint(150 - e) << 23) + (q - 0x800000u));
}

// A gaussiana de meio-lado `lado` (em pixels de `img`) no eixo `passo`, na mesma ordem de contas do Gaussian do AM (a
// do `am-gaussian-blur.xml` e do `am-unsharp-mask.xml`).
vec4 desfocar(sampler2D img, vec2 passo, vec2 st, float lado) {
    if (strength <= 0.0) return vec4(0.0);
    float sigma = lado / 2.14596602;
    highp vec3 g;
    g.x = 1.0 / (sqrt(2.0 * PI) * sigma);
    g.y = exp(-0.5 / (sigma * sigma));
    g.z = g.y * g.y;
    vec4 soma = vec4(0.0);
    highp float total = 0.0;
    soma += texture(img, st) * g.x;
    total += g.x;
    for (float i = 1.0; i <= lado; i += 2.0) {
        float d0 = i;
        float d1 = i + 1.0;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p0 = g.x;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p1 = g.x;
        float par = p0 + p1;
        float d = (d0 * p0 + d1 * p1) / par;
        vec2 stL = st - d * passo;
        vec2 stR = st + d * passo;
        soma += texture(img, stL) * par;
        soma += texture(img, stR) * par;
    }
    return soma / total;
}

// O meio-lado: Tamanho da Borda ÷ 2 × 1,14 ÷ 4 ÷ 3 da diagonal da imagem CHEIA (o `acPreviewSize` do AM).
float ladoDoDesfoque() {
    return strength / 2.0 * 1.14 / 4.0 / 3.0 * length(vec2(textureSize(pre, 0)));
}

// A volta da `acCamadaParaTela`: UV da tela → UV do buffer da camada.
vec2 naCamada(vec2 t) {
    vec3 c = inverse(acCamadaParaTela) * vec3(t, 1.0);
    return c.xy / c.z;
}

// ---------------------------------------------------------------- daqui até o `main`, as funções do AM, linha por linha

float saturate(float v) { return clamp(v, 0., 1.); }

mat2 rot2(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c,s,-s,c);
}

vec4 composite( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
}

float sampleGrain(vec2 uv, int grainType, float gamma, float contrast, float scale, float angle, vec2 offset, bool invert) {

    uv -= 0.5;
    uv *= rot2(angle*0.0174533);
    uv /= scale;
    uv += 0.5;
    uv -= offset * vec2(1., -1.) / 500.;
    uv = fract(uv);

    float grainLuma;
    if( grainType == 1 ) {
        grainLuma = texture(grunge_a,uv).r;
    } else if( grainType == 2 ) {
        grainLuma = texture(grunge_a,uv).g;
    } else if( grainType == 3 ) {
        grainLuma = texture(grunge_a,uv).b;
    } else if( grainType == 4 ) {
        grainLuma = texture(grunge_b,uv).r;
    } else if( grainType == 5 ) {
        grainLuma = texture(grunge_b,uv).g;
    } else if( grainType == 6 ) {
        grainLuma = texture(grunge_b,uv).b;
    } else if( grainType == 7 ) {
        grainLuma = dot(texture(grunge_a,uv).rgb, vec3(1.)) / 3.;
    } else if( grainType == 8 ) {
        grainLuma = dot(texture(grunge_b,uv).rgb, vec3(1.)) / 3.;
    } else if( grainType == 9 ) {
        grainLuma = dot(texture(grunge_b,uv).rb, vec2(1.)) / 2.;
    } else if( grainType == 10 ) {
        uv *= 16.;
        vec2 st = fract(uv);
        vec2 id = floor(uv);
        if( mod(id.x + id.y,2.) == 0. ) {
            st = st.yx;
        }
        float pp = 6.;
        float p = pow(sin(st.x*3.14159*1.),pp);
        st = st.yx;
        float q = clamp(pow(sin(st.x*3.14159*1.),pp),0.,1.);
        p += q * pow((1.-p),10.);
        grainLuma = p;
    } else if( grainType == 11 ) {
        vec2 st = uv * 16.;
        vec2 id = floor(st);
        st = fract(st);
        if( mod(id.x + id.y,2.) == 0. ) {
            st = st.yx;
        }
        float pp = 6.;
        float p = pow(sin(st.x*3.14159*1.),pp);
        st = st.yx;
        float q = clamp(pow(sin(st.x*3.14159*1.),pp),0.,1.);
        p += q * pow((1.-p),10.);
        p = saturate(p);
        float tc = texture(grunge_b,uv).b;
        grainLuma = p * abs(p-tc);
    } else if( grainType == 12 ) {
        grainLuma = sin(uv.y*30.*3.14159)*0.5+0.5;
    } else if( grainType == 13 ) {
        grainLuma = min(sin(uv.y*30.*3.14159)*0.5+0.5,sin(uv.x*30.*3.14159)*0.5+0.5);
    } else if( grainType == 14 ) {
        grainLuma = (sin(uv.y*30.*3.14159)*sin(uv.x*30.*3.14159))*0.5+0.5;
    } else if( grainType == 15 ) {
        grainLuma = uv.y;
    } else if( grainType == 16 ) {
        grainLuma = 1.0;
    } else {
        grainLuma = 0.5;
    }

    grainLuma = saturate(((grainLuma-0.5) * (1.+contrast)) + 0.5);
    grainLuma = pow(grainLuma,1.0/gamma);
    if( invert )
        grainLuma = 1.-grainLuma;

    return grainLuma;

}

vec2 applyDisplace(vec2 displace, vec4 blurColor, vec2 offset, bool fromCtr, int region, vec2 uv, int grainType, float gamma, float contrast, float scale, float angle, vec2 texOffset) {

    float p;
    if( region == 1) {  // Edge
        p = 1. - saturate((blurColor.a-0.5) * 2.);
    } else if( region == 2 ) {  // Center
        p = saturate((blurColor.a-0.5) * 2.);
    } else if( region == 3 ) {  // Fill
        p = 1.;
    } else {
        p = 0.;
    }

    float g = sampleGrain( uv, grainType, gamma, contrast, scale, angle, texOffset, false);

    if( fromCtr ) {
        g = (g - 0.5) * 2.;
    }

    return displace + (offset * vec2(1.,-1.) / 2000.) * g * p;
}

vec4 blendGrain(vec4 baseColor, vec4 originalColor, vec4 blurColor, vec4 color, float alpha, int blendMode, int region, float spread, float rawChoke, float burn, vec2 uv, int grainType, float gamma, float contrast, float scale, float angle, vec2 offset, bool invert, bool light, float lightAngle) {

    float choke = clamp(rawChoke,0.,0.999);

    float p;
    float m;
    if( region == 1) {  // Edge
        m = baseColor.a;
        p = 1. - saturate((blurColor.a-0.5) * 2.);
    } else if( region == 2 ) {  // Center
        m = baseColor.a;
        p = saturate((blurColor.a-0.5) * 2.);
    } else if( region == 3 ) {  // Fill
        m = baseColor.a;
        p = 1.;
    } else if( region == 4 ) {  // Glow
        m = 1.-baseColor.a;
        p = saturate(blurColor.a * 2. - baseColor.a);
    } else {
        m = 0.;
        p = 0.;
    }

    p = saturate((p-choke)/(max(1.-spread,choke+0.0001)-choke));
    float g;
    if( light ) {
        vec2 lv = vec2(.002, 0.) * rot2(lightAngle*0.0174533);
        float g1 = sampleGrain( uv+lv, grainType, gamma, contrast, scale, angle, offset, invert);
        float g2 = sampleGrain( uv-lv, grainType, gamma, contrast, scale, angle, offset, invert);
        g = saturate((g1-g2)*5.);
    } else {
        g = sampleGrain( uv, grainType, gamma, contrast, scale, angle, offset, invert);
    }

    vec4 c = color;
    if( burn < 0.0 ) {
        c.rgb = mix(c.rgb, 1.-(1.-c.rgb) * (1.-(0.5+c.rgb*0.5)), -burn * g*g );
    } else {
        c.rgb = mix(c.rgb, c.rgb * c.rgb * 0.25, burn * g * g );
    }
    c *= alpha * p * g;

    if( region==4 ) {
        return composite(baseColor,c * m);
    } else if( blendMode==1 ) { // Multiply
        vec3 baseRgb = baseColor.rgb / max(baseColor.a,0.00001);
        vec3 rgb = c.rgb / max(c.a,0.00001);
        vec3 adj = baseRgb * rgb;
        return composite(baseColor,vec4(adj,1.) * c.a * baseColor.a);
    } else if( blendMode==2 ) { // Screen
        vec3 baseRgb = baseColor.rgb / max(baseColor.a,0.00001);
        vec3 rgb = c.rgb / max(c.a,0.00001);
        vec3 adj = 1. - ((1.-baseRgb) * (1.-rgb));
        return composite(baseColor,vec4(adj,1.) * c.a * baseColor.a);
    } else if( blendMode==3 ) { // Punch out
        return baseColor * (1.-c.a);
    } else if( blendMode==4 ) { // Copy original
        return composite(baseColor,originalColor * (c.a * m));
    } else { // Normal
        return composite(baseColor,c * m);
    }

}

void main() {
    if (acPass == 0) {
        // A camada do AM chega pré-multiplicada EM 8 BITS, pelo mais perto (o premul do Android); no opaco a cor já é o
        // float da textura, bit a bit.
        vec4 c = texture(inputImg, acScreenNorm);
        vec3 p = c.rgb;
        if (c.a < 1.0) {
            vec3 k = floor(c.rgb * c.a * 255.0 + 0.5);
            p = vec3(oitoBits(k.r), oitoBits(k.g), oitoBits(k.b));
        }
        fragColor = vec4(p, c.a);
        return;
    }
    if (acPass == 1) {
        fragColor = texture(pre, acScreenNorm);
        return;
    }
    if (acPass == 2) {
        vec2 passo = vec2(1.0 / vec2(textureSize(downImg, 0)).x, 0.0);
        fragColor = desfocar(downImg, passo, acScreenNorm, ladoDoDesfoque());
        return;
    }
    if (acPass == 3) {
        // Na tela a entrada chega de pé (t = 0 embaixo, como no AM): o passo aponta para CIMA e a soma do par fica na
        // mesma ordem da dele (o de baixo primeiro). Deitada, o passo vira para baixo.
        float cima = acEntradaDePe == 1 ? 1.0 : -1.0;
        vec2 passo = vec2(0.0, cima / vec2(textureSize(blurH, 0)).y);
        vec4 r = desfocar(blurH, passo, acScreenNorm, ladoDoDesfoque());
        // Tamanho da Borda 0: o Gaussian do AM lê a própria camada aqui (na meia resolução: a média de 2 × 2).
        fragColor = strength <= 0.0 ? texture(pre, acScreenNorm) : r;
        return;
    }
    if (acPass == 4) {
        fragColor = texture(blurV, acScreenNorm);
        return;
    }
    if (acPass == 5) {
        // O `main` do Grunge do AM, na mesma ordem. A coordenada da camada do AM: o retângulo do conteúdo de 0 a 1, com
        // o meio no meio do buffer (que cobre a composição, `acTamanhoDaTela`) e o Y para CIMA (o do buffer de camada
        // do Nova cresce para baixo).
        // As chaves `d1active`, `d2active` e `c1active` não entram aqui, como no AM: lá elas só fariam acender controles
        // que já nascem acesos (sem `enabled="false"`). Um Deslocamento empurra sempre que for ≠ 0, e a Sobreposição
        // mistura sempre pelo Montante. Ficam no painel porque o projeto do AM as traz.
        vec4 blurTexColor = texture(blurBuf, acScreenNorm);
        vec2 uv = 0.5 + (naCamada(acTela(acScreenNorm)) - 0.5) * acTamanhoDaTela / acTamanhoDaCamada;
        uv.y = 1.0 - uv.y;
        uv.x *= acTamanhoDaCamada.x / acTamanhoDaCamada.y;

        vec2 displace = vec2(0.);

        displace = applyDisplace(displace,blurTexColor,d1offset,d1fromctr,d1region,uv,int(d1grain),d1gamma,d1contrast,d1scale,d1angle,d1toffset);
        uv += displace;
        displace = applyDisplace(displace,blurTexColor,d2offset,d2fromctr,d2region,uv,int(d2grain),d2gamma,d2contrast,d2scale,d2angle,d2toffset);
        uv += displace;

        displace.x *= acTamanhoDaTela.x / acTamanhoDaTela.y;

        // A imagem deslocada, na tela, no `pre` (a camada pré-multiplicada de 8 bits, filtro linear da GPU): a textura
        // do AM. Deitada, o Y da tela vira.
        vec2 sentido = vec2(1.0, acEntradaDePe == 1 ? 1.0 : -1.0);
        vec4 texColor = texture(pre, acScreenNorm + displace * sentido);

        texColor = mix(texColor,fillColor*texColor.a,fillColorBlend);

        vec4 result = texColor;

        result = blendGrain(result, texColor, blurTexColor, t1color, t1alpha, t1blendMode, t1active ? t1region : 0, t1spread, t1choke, t1burn, uv, int(t1grain), t1gamma, t1contrast, t1scale, t1angle, t1offset, t1invert, t1light, t1lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t2color, t2alpha, t2blendMode, t2active ? t2region : 0, t2spread, t2choke, t2burn, uv, int(t2grain), t2gamma, t2contrast, t2scale, t2angle, t2offset, t2invert, t2light, t2lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t3color, t3alpha, t3blendMode, t3active ? t3region : 0, t3spread, t3choke, t3burn, uv, int(t3grain), t3gamma, t3contrast, t3scale, t3angle, t3offset, t3invert, t3light, t3lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t4color, t4alpha, t4blendMode, t4active ? t4region : 0, t4spread, t4choke, t4burn, uv, int(t4grain), t4gamma, t4contrast, t4scale, t4angle, t4offset, t4invert, t4light, t4lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t5color, t5alpha, t5blendMode, t5active ? t5region : 0, t5spread, t5choke, t5burn, uv, int(t5grain), t5gamma, t5contrast, t5scale, t5angle, t5offset, t5invert, t5light, t5lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t6color, t6alpha, t6blendMode, t6active ? t6region : 0, t6spread, t6choke, t6burn, uv, int(t6grain), t6gamma, t6contrast, t6scale, t6angle, t6offset, t6invert, t6light, t6lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t7color, t7alpha, t7blendMode, t7active ? t7region : 0, t7spread, t7choke, t7burn, uv, int(t7grain), t7gamma, t7contrast, t7scale, t7angle, t7offset, t7invert, t7light, t7lightAngle);
        result = blendGrain(result, texColor, blurTexColor, t8color, t8alpha, t8blendMode, t8active ? t8region : 0, t8spread, t8choke, t8burn, uv, int(t8grain), t8gamma, t8contrast, t8scale, t8angle, t8offset, t8invert, t8light, t8lightAngle);

        // O corte em 0..1 é o do alvo de 8 bits; escrito para o projeto de 32 bits sair igual.
        fragColor = clamp(result, 0.0, 1.0);
        return;
    }

    // A saída do AM (pré-multiplicada, já em 8 bits) em cor reta.
    vec4 q = texture(grunge, acScreenNorm);
    fragColor = q.a > 0.0 ? vec4(min(q.rgb / q.a, vec3(1.0)), q.a) : vec4(0.0);
}
